Rules.InvariantScript:
If(
    Upper(
        Coalesce(
            galBoardRecords.Selected.TargetMatchMtx,
            ""
        )
    ) = "NO MATCH",
    FontWeight.Bold,
    FontWeight.Normal
)

If(
    Upper(
        Coalesce(
            galBoardRecords.Selected.TargetMatchMtx,
            ""
        )
    ) = "NO MATCH",
    Color.Red,
    ColorValue("#03173E")
)

If(
    IsBlank(galBoardRecords.Selected),
    Notify(
        "Select a configuration record before modifying worksheet values.",
        NotificationType.Warning
    ),
    Set(
        gblSelectedAccommodation,
        galBoardRecords.Selected
    );
    Set(
        gblDashboardExpanded,
        false
    );
    Navigate(
        scrAccommodations,
        ScreenTransition.Fade
    )
)
